Set<int> fn0(String barcode) {
  Set<int> result = {};
  int lastIndex = barcode.lastIndexOf('#');
  if (lastIndex == -1) return result;
  String digits = barcode.substring(0, lastIndex);
  int checkDigit = int.tryParse(barcode.substring(lastIndex + 1)) ?? 0;
  int expectedCheckDigit = (0 - (digits.codeUnits.fold(0, (a, b) => a + b) % 10)) % 10;
  if (checkDigit != expectedCheckDigit) return result;
  int i = 0;
  while (i < digits.length) {
    int start = i;
    while (i < digits.length && digits.codeUnits[i] >= 48 && digits.codeUnits[i] <= 57) i++;
    int runLength = i - start;
    if (runLength % 2 == 0) result.add(digits.codeUnits[start] - 48);
  }
  return result;
}

