bool fn0(String password, String forbidden) {
  Set<String> forbiddenList = {};
  int i = 0;
  while (i < forbidden.length) {
    while (i < forbidden.length && forbidden.codeUnitAt(i) < 32) {
      i++;
    }
    if (i >= forbidden.length) {
      break;
    }
    String token = forbidden.substring(i, i + 1);
    i++;
    if (token.length > 1) {
      continue;
    }
    int code = forbidden.codeUnitAt(i);
    if (code < 97 || code > 122) {
      continue;
    }
    forbiddenList.add(token);
  }
  if (forbiddenList.contains(password)) {
    return false;
  }
  int dot = password.lastIndexOf('.');
  if (dot < 0) {
    return true;
  }
  String token = password.substring(0, dot);
  return forbiddenList.contains(token) && int.tryParse(password.substring(dot + 1)) == 65;
}

