Set<int> fn0(String row) {
  Set<int> peaks = {};
  int colon = row.lastIndexOf(':');
  if (colon == -1) return peaks;
  String heightStr = row.substring(colon + 1);
  int? height;
  try {
    height = int.tryParse(heightStr);
  } catch (_) {
    return peaks;
  }
  if (height == null) return peaks;
  if (height < 0) {
    peaks.add(0);
    return peaks;
  }
  int star = heightStr.indexOf('*');
  if (star == -1) return peaks;
  String section = heightStr.substring(0, star);
  int run = 0;
  for (int i = 0; i < section.length; i++) {
    String ch = section[i];
    if (ch == '.') {
      run++;
    } else if (ch == '-') {
      if (run > 0) peaks.add(run);
      run = 0;
    } else {
      return peaks;
    }
  }
  if (run > 0) peaks.add(run);
  int repeatCount = 0;
  bool hasDigit = false;
  for (int i = 0; i < heightStr.length; i++) {
    String c = heightStr[i];
    if (c == '#') {
      repeatCount++;
    } else if (c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57) {
      hasDigit = true;
    } else {
      return peaks;
    }
  }
  if (!hasDigit || repeatCount == 0) return peaks;
  if (repeatCount > 1) {
    peaks.add(repeatCount);
  }
  int peak = 0;
  for (int r = 0; r < repeatCount; r++) {
    int count = r < heightStr.length ? int.tryParse(heightStr[r]) ?? 0 : 0;
    if (count > peak) peak = count;
  }
  peaks.add(peak);
  return peaks;
}

