Set<int> fn0(String row, int minLength) {
  Set<int> result = {};
  if (row.isEmpty || minLength <= 0) {
    return result;
  }

  int runStart = row.lastIndexOf('#');
  if (runStart == -1) {
    return result;
  }

  int runLength = row.length - runStart;
  if (runLength < minLength) {
    return result;
  }

  int left = 0;
  int right = runLength - 1;
  while (left < right) {
    int mid = (left + right) ~/ 2;
    String centerChar = row[mid + runStart];
    if (centerChar.toLowerCase() >= 'a'.toLowerCase() && centerChar.toLowerCase() <= 'm'.toLowerCase()) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  int firstCenter = left;
  if (firstCenter > 0) {
    int centerCode = row[firstCenter + runStart].toLowerCase().codeUnitAt(0);
    result.add(centerCode % 13 + 1);
  }

  int lastCenter = runLength - firstCenter - 1;
  int lastCenterCode = row[lastCenter + runStart].toLowerCase().codeUnitAt(0);
  result.add(lastCenterCode % 13 + 1);

  return result;
}

