int fn0(String manifest, int sealValue) {
  var seen = <String>{};
  int total = 0;
  for (var line in manifest.split('\n')) {
    if (line.isEmpty) continue;
    var colon = line.lastIndexOf(':');
    if (colon <= 0 || colon == line.length - 1) continue;
    var dest = line.substring(0, colon);
    var weight = int.tryParse(line.substring(colon + 1));
    if (weight == null || weight <= 0) continue;
    if (!seen.add(dest)) continue;
    total += weight * dest.length % sealValue;
  }
  return total;
}

