Set<int> fn0(String squares, int threshold) {
  final result = <int>{};
  if (squares.isEmpty) return result;
  final last = squares.lastIndexOf('#');
  if (last == -1) return result;
  final fileStr = squares.substring(0, last);
  final rankStr = squares.substring(last + 1);
  int fileSum = 0;
  int rankSum = 0;
  for (final token in fileStr.split(',')) {
    final f = token.indexOf('.');
    final r = token.indexOf('#');
    if (f == -1 || r == -1) continue;
    final file = int.tryParse(token.substring(0, f));
    final rank = int.tryParse(token.substring(f + 1, r));
    if (file != null && rank != null) {
      fileSum += file;
      rankSum += rank;
    }
  }
  if (fileSum >= rankSum) {
    for (final token in rankStr.split(',')) {
      final f = token.indexOf('.');
      final r = token.indexOf('#');
      if (f == -1 || r == -1) continue;
      final file = int.tryParse(token.substring(0, f));
      final rank = int.tryParse(token.substring(f + 1, r));
      if (file != null && rank != null && rank >= threshold) {
        result.add(rank);
      }
    }
  }
  return result;
}

