  for (var code in codes) {
    freq[code] = (freq[code] ?? 0) + 1;
    seen.add(code);
  }
  Map<String, int> freqOfFreq = {};
  for (var c in seen) {
    freqOfFreq[freq[c]!] = (freqOfFreq[freq[c]] ?? 0) + 1;
  }
  List<String> result = freqOfFreq.keys.toList();
  result.sort((a, b) {
    int cmp = freqOfFreq[b]!.compareTo(freqOfFreq[a]!);
    if (cmp != 0) return cmp;
    return a.compareTo(b);
  });
