  List<String> wordBreak2(String s, List<String> wordDict) {
    int n = s.length;
    Set<String> wordSet = wordDict.toSet();
    Map<int, List<String>> subwordDict = {};
    for (String word in wordDict) {
      if (word.length <= n) {
        subwordDict.containsKey(word.length)
            ? subwordDict[word.length]!.add(word)
            : subwordDict[word.length] = [word];
      }
    }
    List<String> results = [];
    List<bool> dp = List.filled(n + 1, false);
    dp[0] = true;

    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] && subwordDict.containsKey(i - j)) {
          List<String> subwords = subwordDict[i - j]!;
          for (String subword in subwords) {
            if (wordSet.contains(subword)) {
              dp[i] = true;
              break;
            }
          }
        }
      }
    }

    if (!dp[n]) return [];

    List<String> segmentations = [];
    List<int> path = List.filled(n + 1, 0); 
    path[0] = -1;

