    List<bool> dp = List.filled(s.length + 1, false);
    dp[0] = true;
    Map<String, bool> wordMap = {};
    for (String word in wordDict) {
      wordMap[word] = true;
    }
    for (int i = 1; i <= s.length; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] && wordMap.containsKey(s.substring(j, i))) {
          dp[i] = true;
          break;
        }
      }
    }
    return dp[s.length];
  }

  bool allSegments(String s, List<String> wordDict) {
    if (wordDict.isEmpty) return false;
    List<String> result = [];
    Set<String> wordSet = wordDict.toSet();
    List<bool> dp = List.filled(s.length + 1, false);
    dp[0] = true;
    Map<String, List<String>> prefixMap = {};
    for (String word in wordDict) {
      prefixMap.putIfAbsent(word, () => []);
    }
    for (int i = 1; i <= s.length; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] && wordSet.contains(s.substring(j, i))) {
          for (String word in prefixMap[s.substring(j, i)]!) {
            result.add(word + s.substring(i, j) + word);
          }
        }
      }
    }
    return result.isNotEmpty;
  }

