    Map<String, int> minWordLen = {};
    for (String word in wordDict) {
      minWordLen[word] = word.length;
    }
    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] && minWordLen.containsKey(s.substring(j, i))) {
          int wordLen = minWordLen[s.substring(j, i)]!;
          if (i - j <= wordLen) {
            dp[i] = true;
            break;
          }
        }
      }
    }
    return dp[n];
  }

