  bool canSegment(List<String> words, String text) {
    if (words.isEmpty || text.isEmpty) return false;
    int m = words.length;
    int n = text.length;
    List<List<bool>> dp = List.generate(m + 1, (_) => List.filled(n + 1, false));
    for (int i = 0; i <= m; i++) dp[i][0] = true;
    for (int j = 1; j <= n; j++) {
      for (int i = 0; i < m; i++) {
        if (words[i].length <= j && words[i].startsWith(text.substring(j - words[i].length, j))) {
          dp[i][j] = dp[i][j - words[i].length] || true;
        }
      }
    }
    return dp[0][n];
  }

  int minWordBreaks(List<String> words, String text) {
    if (words.isEmpty || text.isEmpty) return 0;
    int m = words.length;
    int n = text.length;
    List<List<int>> dp = List.generate(m + 1, (_) => List.filled(n + 1, 0));
    for (int i = 0; i <= m; i++) dp[i][0] = i;
    for (int j = 1; j <= n; j++) {
      for (int i = 0; i < m; i++) {
        if (words[i].length <= j && words[i].startsWith(text.substring(j - words[i].length, j))) {
          if (dp[i][j - words[i].length] != 0) {
            dp[i][j] = dp[i][j - words[i].length] + 1;
          }
        }
      }
    }
    return dp[0][n];
  }

  void printWordBreak(String word, List<String> words, List<int> counts) {
    int i = 0;
    while (i < counts.length && counts[i] > 0) {
      print('$word:${counts[i]}: ${words[i]}');
      i++;
    }
  }

  bool canSegment(String word, List<String> words) {
    List<int> counts = List.filled(words.length, 0);
    for (int i = 0; i < words.length; i++) {
      if (words[i] == word) { counts[i] = 1; break; }
    }
    for (int i = 0; i < words.length; i++) {
      if (counts[i] == 1) return true;
    }
    return false;
  }

  List<List<String>> getAllSegmentations(String word, List<String> words) {
    Map<String, List<String>> memo = {};
    List<String> segmentations = [];
    void backtrack(int start) {
      if (start == word.length) {
        if (word.isNotEmpty) segmentations.add(word);
        return;
      }
      for (int i = start; i < word.length; i++) {
        String current = word.substring(start, i + 1);
        if (memo.containsKey(current)) {
          List<String> matches = memo[current]!;
          for (String match in matches) {
            backtrack(i + 1);
          }
        }
      }
    }
    for (int i = 0; i < words.length; i++) {
      if (canSegment(word, words[i])) {
        String key = word + '-' + words[i];
        memo[key] = [];
      }
    }
    backtrack(0);
    return segmentations;
  }

  List<List<String>> wordBreakII(List<String> words, String text) {
    Map<String, bool> dp = {};
    for (String word in words) {
      dp[word] = false;
    }
    dp[text] = true;
    List<List<String>> segmentations = [];
    for (int i = 0; i < text.length; i++) {
      String prefix = text.substring(0, i + 1);
      if (dp.containsKey(prefix)) {
        List<String> segments = getAllSegmentations(prefix, words);
        for (String seg in segments) {
          dp[seg] = true;
          segmentations.add([prefix, seg]);
        }
      }
    }
    return segmentations;
  }

