bool _canSegment(String word, List<String> dict) {
  Set<String> dictSet = dict.toSet();
  for (int i = 0; i < word.length; i++) {
    String prefix = word.substring(0, i);
    if (dictSet.contains(prefix)) {
      if (_hasPath(word.substring(i + 1), dict, prefix)) {
        return true;
      }
    }
  }
  return false;
}

bool _hasPath(String word, Map<String, Set<String>> wordNet, String prefix) {
  if (word == wordNet.keys.contains(word) ? wordNet[word]! : wordNet[word]!) {
    return true;
  }
  for (String neighbor in wordNet[word]!) {
    if (_hasPath(neighbor, wordNet, "$prefix/$word")) {
      return true;
    }
  }
  return false;
}

List<String> _allSeg(String word, List<String> dict) {
  if (word.length <= 2) return [word]; 
  List<String> result = [];
  for (int i = 0; i < word.length; i++) {
    String prefix = word.substring(0, i);
    if (dict.contains(prefix)) {
      String suffix = word.substring(i + 1);
      List<String> sub = _allSeg(suffix, dict);
      for (String subword in sub) {
        result.add("$prefix/$subword");
      }
    }
  }
  return result;
}

bool _isPermutation(String a, String b) {
  if (a.length != b.length) return false;
  int aCount = 0, bCount = 0;
  for (int i = 0; i < a.length; i++) {
    if (a[i] == b[i]) {
      aCount++;
    } else {
      bCount++;
    }
  }
  return aCount == bCount;
}

bool _isAnagram(String a, String b) {
  int aCount = 0, bCount = 0;
  for (int i = 0; i < a.length; i++) {
    if (a[i] == b[i]) {
      aCount++;
    } else {
      bCount++;
    }
  }
  return aCount == bCount;
}

