    } else if (cmd == 'ADD') {
      if (stack.length < 2) return {'error': 'Stack underflow'};
      int start = stack.removeLast();
      int end = stack.removeLast();
      int seconds = end * 60 + start;
      history.add('ADD $seconds');
      logs[logs.length - 1].add(seconds);
      total += seconds;
    } else if (cmd == 'UNDO') {
      if (history.isEmpty) return {'error': 'No operations to undo'};
      String lastOp = history.removeLast();
      if (lastOp == 'BEGIN') {
        stack.removeLast();
      } else if (lastOp == 'END') {
        int s = stack.removeLast();
        int b = stack.removeLast();
        total -= s * 60 + b;
      } else if (lastOp == 'ADD') {
        int s = stack.removeLast();
        int e = stack.removeLast();
        total -= e * 60 + s;
      }
      if (stack.isNotEmpty) stack[stack.length - 1]++;
    } else {
      int sec = int.parse(cmd);
      stack[stack.length - 1] += sec;
      total += sec;
      history.add('$sec');
    }
