  bool binarySearch(List<String> rows, String pattern, int left, int right) {
    if (left > right) return false;
    if (rows[left].isEmpty) return false;
    int patternLength = pattern.length;
    for (int i = 0; i < patternLength; i++) {
      if (rows[left][i] != pattern[i]) return false;
    }
    if (rows[right].isEmpty) return false;
    int low = left;
    int high = right;
    while (low < high) {
      int mid = (low + high) >> 1;
      if (rows[mid].isEmpty) {
        low = mid + 1;
        continue;
      }
      for (int i = 0; i < patternLength; i++) {
        if (rows[mid][i] != pattern[i]) {
          low = mid + 1;
          break;
        }
      }
      if (low < mid) {
        high = mid;
      } else {
        low = mid + 1;
      }
    }
    List<int> positions = [];
    for (int i = 0; i < patternLength; i++) {
      if (rows[low][i] == pattern[i]) {
        positions.add(low);
      }
    }
    if (positions.isNotEmpty) {
      return true;
    }
    return false;
  }

  List<String> rows = [
