  ];

  List<String> texts = [
    'EXAMPLE',
    'Pattern not found.',
    'HERE IS A SIMPLE EXAMPLE'
  ];

  List<List<int>> patternsTable = [];
  List<int> row = [];
  List<List<int>> textTable = [];

  void preparePatternsTable(List<String> patterns) {
    for (String pattern in patterns) {
      row.clear();
      for (int i = 0; i < pattern.length; i++) {
        if (pattern[i] == ' ') {
          row.add(-1);
        } else {
          row.add(i);
        }
      }
      patternsTable.add(row);
    }
  }

  void prepareTextTable(List<String> texts) {
    for (String text in texts) {
      List<int> row = [];
      for (int i = 0; i < text.length; i++) {
        if (text[i] == ' ') {
          row.add(-1);
        } else {
          row.add(i);
        }
      }
      textTable.add(row);
    }
  }

  void searchPattern(String pattern, String text) {
    int pLen = pattern.length;
    int tLen = text.length;

    List<List<int>> pTable = List.generate(pLen, (i) => List<int>.filled(tLen, 0));

    for (int i = 0; i < pLen; i++) {
      for (int j = 0; j < tLen; j++) {
        if (pattern[i] == text[j]) {
          pTable[i][j] = i;
        }
      }
    }

    int matches = 0;
    int lastEnd = -1;

    for (int i = 0; i < pLen; i++) {
      for (int j = 0; j < tLen; j++) {
        if (pTable[i][j] != -1) {
          matches++;
          lastEnd = j;
        }
      }
    }

    if (matches > 0) {
      List<int> ends = [];
      int k = lastEnd;
      while (k >= 0) {
        ends.add(k);
        k--;
      }
      print('Pattern found at positions: ${ends.join(' ')}');
    } else {
      print('Pattern not found.');
    }
  }

  preparePatternsTable(patterns);
  prepareTextTable(texts);

  for (int i = 0; i < patterns.length; i++) {
    searchPattern(patterns[i], texts[i]);
  }
}

