int _generateCombinations(List<String> items, int index, int k) {
  if (k == 0) return 1;
  if (index >= items.length) return 0;

  int count = 0;
  for (int i = index; i < items.length; i++) {
    final String current = items[i];
    final List<String> remaining = List.generate(
      items.length - (i + 1),
      (j) => j >= i + 1 ? items[j + 1] : current,
    );
    count += _generateCombinations(remaining, i + 1, k - 1);
  }

  return count;
}

