    3: [1, 2, 6],
    4: [1, 5],
    5: [2, 4],
    6: [3],
  };

  bool unionFind(int x, int y) {
    if (x == y) return false;

    bool xRoot = find(x);
    bool yRoot = find(y);

    if (xRoot && yRoot) return false;

    if (xRoot) {
      unions(yRoot, xRoot);
      return true;
    }

    if (yRoot) {
      unions(xRoot, yRoot);
      return true;
    }

    return false;
  }

  int find(int x) {
    if (x == 0) return x;
    x = x & (-x); 
    return x;
  }

  void unions(int a, int b) {
    int aRoot = find(a);
    int bRoot = find(b);

    if (aRoot != bRoot) {
      if (aRoot > bRoot) {
        aRoot ^= bRoot;
        bRoot ^= aRoot;
      } else {
        bRoot ^= aRoot;
        aRoot ^= bRoot;
      }
    }
  }

  final Map<int, Set<int>> connectedComponents = {};

  void dfs(int node, Set<int> visited) {
    visited.add(node);

    for (final neighbor in graph[node]!) {
      if (!visited.contains(neighbor)) {
        dfs(neighbor, visited);
      }
    }
  }

  void search(int start) {
    final Set<int> visited = {};
    dfs(start, visited);

    final List<Set<int>> components = [];

    for (final node in visited) {
      final Set<int> component = {};
