bool fn0(List<int> arrivalDays) {
  var seen = <int>{};
  var queue = <int>[];
  for (var day in arrivalDays) {
    if (day < 0) continue;
    if (seen.contains(day)) continue;
    if (queue.isNotEmpty && queue.first == day) continue;
    seen.add(day);
    queue.add(day);
    while (queue.length > 1) {
      var left = queue.removeAt(0);
      if (seen.contains(left)) continue;
      var right = queue.removeLast();
      if (left > right) {
        queue.add(right);
        queue.add(left);
      } else {
        queue.add(left);
        queue.add(right);
      }
    }
    if (queue.isEmpty) return false;
  }
  return queue.length <= 1;
}

