    for (int c = 0; c < width; c++) {
      if (maze[r][c] == '#' || visited.contains(r + ',' + c.toString())) {
        continue;
      }

      String cell = r + ',' + c.toString();
      visited.add(cell);

      int maxDist = 0;
      List<String> queue = <String>[];

      for (int i = 0; i < 4; i++) {
        int nr = r + dirs[i];
        int nc = c + dirsN[i];

        if (nr >= 0 && nr < maze.length && nc >= 0 && nc < width) {
          String neighbor = nr + ',' + nc.toString();

          if (!visited.contains(neighbor)) {
            maxDist++;
            queue.add(neighbor);
          }
        }
      }

      if (maxDist > 0) {
        result.add(cell + ':' + maxDist.toString());
      }

      for (int k = 0; k < 4; k++) {
        int nr = r + dirs[k];
        int nc = c + dirsN[k];

        if (nr >= 0 && nr < maze.length && nc >= 0 && nc < width) {
          String neighbor = nr + ',' + nc.toString();

          if (!visited.contains(neighbor)) {
            visited.add(neighbor);
            int dist = 0;
            queue.add(neighbor);
            while (queue.isNotEmpty) {
              String cell = queue.removeAt(0);
              int colon = cell.indexOf(':');
              if (colon > 0) {
                int d = int.parse(cell.substring(colon + 1));
                if (d > dist) {
                  dist = d;
                }
              }
            }
            result.add(neighbor + ':' + dist.toString());
          }
        }
      }
    }
  }

  result.sort();
  return result;
}

