void solveNQueens(int n) {
  int solutionCount = 0;

  List<List<int>> solutions = List.generate(n, (_) => List.filled(n, 0));

  void place(int row) {
    for (int col = 0; col < n; col++) {
      if (solutions[row][col] == 0) {
        solutions[row][col] = row + 1;
        bool safe = true;

        for (int i = 0; i < row; i++) {
          if (solutions[i][col] == row + 1) {
            safe = false;
            break;
          }
        }

        if (safe) {
          print('Q ${row + 1} at ($col, $row)');
          solutionCount++;
        }
      }
    }
  }

  for (int row = 0; row < n; row++) {
    for (int col = 0; col < n; col++) {
      if (solutions[row][col] == 0) {
        place(row);
        break;
      }
    }
  }

  print('Total solutions: $solutionCount');
  print('---------------------');

  for (int i = 0; i < solutionCount; i++) {
    String solutionRow = '';
    for (int j = 0; j < n; j++) {
      solutionRow += solutions[i][j] == (i + 1) ? 'Q ' : ' ';
    }
    print('Solution $i: $solutionRow');
  }
}

