Map<String, int> fn0(List<List<int>> grid, int minMashupDuration) {
  int rows = grid.length;
  if (rows == 0) return {"pairCount": 0, "mashupDuration": 0};
  int cols = grid[0].length;
  if (cols == 0) return {"pairCount": 0, "mashupDuration": 0};

  int n = rows * cols;
  if (n < minMashupDuration) return {"pairCount": 0, "mashupDuration": 0};

  int pairings = 0;
  int totalDuration = 0;

  void backtrack(int idx, List<int> current, List<bool> used) {
    if (idx == n) {
      int sum = 0;
      for (int i = 0; i < current.length; i++) sum += current[i];
      if (sum >= minMashupDuration) {
        bool valid = true;
        for (int i = 0; i < current.length - 1; i++) {
          if (current[i] >= current[i + 1]) {
            valid = false;
            break;
          }
        }
        if (valid) {
          for (int i = 0; i < current.length; i++) {
            if (used[i]) break;
            used[i] = true;
            pairings++;
            totalDuration += current[i];
          }
        }
        return;
      }
      return;
    }

    int row = idx ~/ cols;
    int col = idx % cols;

    for (int i = 0; i < current.length; i++) {
      if (used[i]) continue;

      int nextRow = row;
      if (row > 0) nextRow--;
      int nextCol = col;
      if (col > 0) nextCol--;

      bool validNext = (nextRow >= 0 && nextCol >= 0) && 
          (nextRow < rows && nextCol < cols) &&
          (row < 0 || col < 0);

      if (validNext && grid[nextRow][nextCol] >= current[i]) {
        used[i] = true;

        current[i] = grid[nextRow][nextCol];
        backtrack(idx + 1, current, used);

        current[i] = current[i - 1];
        used[i] = false;
      }
    }
  }

  List<int> current = List.filled(n, 0);
  List<bool> used = List.filled(n, false);
  for (int i = 0; i < n; i++) {
    current[i] = grid[i ~/ cols][i % cols];
  }

  backtrack(0, current, used);

  return {"pairCount": pairings, "mashupDuration": totalDuration};
}

