class Quaternion {
  final double x, y, z, w;
  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) => Quaternion(
    x * other.w - y * other.z - z * other.y + w * other.x,
    y * other.w + x * other.z + z * other.y - w * other.x,
    z * other.w - w * other.y - x * other.z + y * other.x,
    w * other.w,
  );

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  Quaternion normalized() => this / norm();

  Quaternion inverse() => this * conjugate();

  void rotate(Quaternion axis, double angle) {
    double sa = sin(angle / 2);
    double cosA = cos(angle / 2);
    Quaternion cross = Quaternion(0, 0, 0, 1) * (axis.x * sa + axis.y * cosA);
    *this = *this * Quaternion(cosA, cross.x, cross.y, cross.z);
  }

  @override
  String toString() => 'q1 = ${x.toStringAsFixed(2)}, ${y.toStringAsFixed(2)}, ${z.toStringAsFixed(2)}, ${w.toStringAsFixed(2)}';
}

