  const Quaternion.norm() : this(w * w + x * x + y * y + z * z).sqrt());

  const Quaternion.rotate() : this(
          Math.cos(angle / 2),
          x * Math.sin(angle / 2),
          y * Math.sin(angle / 2),
          z * Math.sin(angle / 2),
        );

  const Quaternion.neg() : this(-w, -x, -y, -z);

  const Quaternion.cross() : this(
          z * y - x * w,
          x * z - y * w,
          y * x - z * w,
        );

  const Quaternion.skew() : this(x * z - y * w, y * z - x * w, x * w - y * z);

  const Quaternion.plus(this.w, this.x, this.y, this.z)
      : this(
          w + other.w,
          x + other.x,
          y + other.y,
          z + other.z,
        );

  const Quaternion.minus(this.w, this.x, this.y, this.z)
      : this(
          w - other.w,
          x - other.x,
          y - other.y,
          z - other.z,
        );

  const Quaternion.times(this.w, this.x, this.y, this.z)
