          w * other.y + x * other.z - y * other.w + z * other.x,
          w * other.z + y * other.x - x * other.y - z * other.w,
        );

  const Quaternion.inverse() : this(
          1 / w,
          x / w,
          y / w,
          z / w,
        );

  const Quaternion.conjugate() : this(w, x, y, -z);

  @override
  String toString() =>
