  final double imaginary2;
  final double imaginary3;

  const Quaternion(this.real, [this.imaginary1 = 0.0, this.imaginary2 = 0.0, this.imaginary3 = 0.0]);

  const Quaternion.unit => const Quaternion(0.0, 1.0, 0.0, 0.0);
  const Quaternion.zero => const Quaternion(0.0, 0.0, 0.0, 0.0);

  const Quaternion.random => const Quaternion(
    random.nextDouble() * 2.0 - 1.0,
    random.nextDouble() * 2.0 - 1.0,
    random.nextDouble() * 2.0 - 1.0,
    random.nextDouble() * 2.0 - 1.0,
  );

  const Quaternion.fromList(List<double> components)
      : real = components[0],
        imaginary1 = components[1],
        imaginary2 = components[2],
        imaginary3 = components[3];

  const Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ, double angle) {
    double sinHalf = sin(angle * 0.5);
    double cosHalf = cos(angle * 0.5);
    return const Quaternion(
      cosHalf * axisX + sinHalf * axisY,
      cosHalf * axisY - sinHalf * axisX,
      sinHalf * axisZ,
      cosHalf * axisZ,
    );
  }

  double length => sqrt(real * real + imaginary1 * imaginary1 + imaginary2 * imaginary2 + imaginary3 * imaginary3);

  double norm => length == 0.0 ? 0.0 : 1.0 / length;

  const Quaternion operator +(const Quaternion other) =>
      const Quaternion(real + other.real, imaginary1 + other.imaginary1, imaginary2 + other.imaginary2, imaginary3 + other.imaginary3);

  const Quaternion operator -(const Quaternion other) =>
      const Quaternion(real - other.real, imaginary1 - other.imaginary1, imaginary2 - other.imaginary2, imaginary3 - other.imaginary3);

  const Quaternion operator *(const Quaternion other) =>
      const Quaternion(
        real * other.real - imaginary1 * other.imaginary1 - imaginary2 * other.imaginary2 - imaginary3 * other.imaginary3,
        real * other.imaginary1 + imaginary1 * other.real - imaginary2 * other.imaginary2 - imaginary3 * other.imaginary3,
        real * other.imaginary2 + imaginary2 * other.real - imaginary1 * other.imaginary1 - imaginary3 * other.imaginary3,
        real * other.imaginary3 + imaginary3 * other.real - imaginary1 * other.imaginary1 - imaginary2 * other.imaginary2,
      );

  const Quaternion operator *(double scalar) =>
      const Quaternion(real * scalar, imaginary1 * scalar, imaginary2 * scalar, imaginary3 * scalar);

  const Quaternion conjugate => const Quaternion(real, -imaginary1, -imaginary2, -imaginary3);

  const Quaternion inverse => conjugate * norm;

  const Quaternion normalized => conjugate / length;

  @override
  String toString() =>
      'q1 = ${real.toStringAsFixed(3)} + ${imaginary1.toStringAsFixed(3)}i + ${imaginary2.toStringAsFixed(3)}j + ${imaginary3.toStringAsFixed(3)}k';
}

