  Quaternion.random() : this(0.5 * random(), 0.5 * random(), 0.5 * random(), 0.5 * random());

  Quaternion.fromList(List<double> list) : this(list[0], list[1], list[2], list[3]);

  Quaternion.identity() : this(1.0, 1.0, 1.0, 1.0);

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.one() : this(1.0, 1.0, 1.0, 1.0);

  Quaternion.fromAxisAngle(double angle, double x, double y, double z) {
    double s = sin(angle / 2);
    double c = cos(angle / 2);
    double sx = x * s;
    double sy = y * s;
    double sz = z * s;
    return Quaternion(sx, sy, sz, c);
  }

  double length() => sqrt(x * x + y * y + z * z + w * w);

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion inverse() => Quaternion(x * x + y * y + z * z + w * w, -x, -y, -z) / length();

  Quaternion normalize() {
    double n = length();
    if (n == 0.0) return Quaternion.zero();
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion operator+(Quaternion q) => Quaternion(x + q.x, y + q.y, z + q.z, w + q.w);

  Quaternion operator-(Quaternion q) => Quaternion(x - q.x, y - q.y, z - q.z, w - q.w);

  Quaternion operator*(Quaternion q) {
    return Quaternion(
      x * q.w + q.x * w,
      y * q.w + q.y * w,
      z * q.w + q.z * w,
      x * q.x + y * q.y + z * q.z + w * q.w,
    );
  }

  Quaternion operator*=(Quaternion q) {
    x = x * q.w + q.x * w;
    y = y * q.w + q.y * w;
    z = z * q.w + q.z * w;
    w = x * q.x + y * q.y + z * q.z + w * q.w;
  }

  @override
  String toString() => 'q1 = $x + $y * i + $z * j + $w * k';
}

