      width = cells.length;
    } else if (width != cells.length) {
      return {};
    }
  }

  if (counts.isEmpty) {
    return {};
  }

  String bestKey = '';
  int bestCount = -1;

  for (String key in counts.keys) {
    int count = counts[key]!;

    if (count > bestCount ||
        (count == bestCount &&
            (bestKey.isEmpty || key.compareTo(bestKey) < 0))) {
      bestCount = count;
      bestKey = key;
    }
  }

  return {'$bestKey': bestCount};
}

