Map<String, int> fn0(List<String> shelfCodes, List<int> levels, int threshold) {
  int n = shelfCodes.length;
  if (n == 0) return {};
  List<int> dp = List.filled(n, 0);
  dp[0] = levels[0];
  for (int i = 1; i < n; i++) {
    if (levels[i] >= threshold) {
      dp[i] = dp[i - 1] + levels[i];
    } else {
      dp[i] = levels[i];
    }
  }
  Map<String, int> result = {};
  int idx = n - 1;
  while (idx >= 0) {
    String code = shelfCodes[idx];
    result[code] = dp[idx];
    idx--;
  }
  return result;
}

