  if (markers.isEmpty) return {};
  int n = dna.length;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    dp[i] = dp[i - 1] + 1;
    if (i >= 4 && dp[i] < dp[i - 4] + 1) {
      dp[i] = dp[i - 4] + 1;
    }
  }
  Map<String, int> result = {};
  for (int j = 0; j < markers.length; j++) {
    String marker = markers[j];
    if (marker.length <= 4) {
      result[marker] = dp[n];
    } else {
      int left = dp[n - marker.length];
      int right = dp[n] - dp[n - marker.length];
      result[marker] = left > right ? left : right;
    }
  }
  return result;
}

