    4: [],
  };

  int source = 0;

  double dijkstra(Map<int, List<MapEntry<int, double>>> graph, int source) {
    Map<int, double> distances = {};
    Set<int> visited = {};

    for (int v = 0; v < graph.length; v++) {
      distances[v] = double.infinity;
      visited.add(v);
    }
    distances[source] = 0;

    for (int count = 0; count < graph.length - 1; count++) {

      int minDist = double.infinity;
      int u = 0;

      for (int v = 0; v < graph.length; v++) {
