  int left = startDay - 1;
  int right = endDay - 1;
  int i = left;
  int sum = 0;
  while (i <= right) {
    sum += readings[i];
    while (i <= right && sum > windowSize) {
      sum -= readings[left];
      left++;
    }
    if (i - left >= windowSize) {
      for (int j = i; j <= right && j - left >= windowSize; j++) {
        if (readings[j] > 0) sum += readings[j];
      }
