      for (int k = i; k <= right && k - left + 1 == windowSize; k++) {
        if (readings[k] > 0) sum += readings[k];
      }
      if (i > left) {
        for (int m = left; m <= i && m - left + 1 == windowSize; m++) {
          if (readings[m] > 0) sum += readings[m];
        }
      }
    }
    if (sum > 0) {
      for (int l = i; l <= right && l - i + 1 == windowSize; l++) {
        if (readings[l] > 0) sum += readings[l];
      }
    }
    if (i < right) {
      for (int r = right; r > i && r - i + 1 == windowSize; r--) {
        if (readings[r] > 0) sum += readings[r];
      }
    }
    while (i <= right && readings[i] == 0) i++;
    while (left <= i && readings[left] == 0) left++;
  }
