  final Map<String, List<String>> userRole = {};
  for (int i = 0; i < _users.length; i++) {
    userRole[_users[i]] = _roles[i];
  }

  const List<String> _resources = ['document1', 'document2', 'sensitive_data'];
  const List<String> _actions = ['view', 'read', 'write', 'delete', 'admin'];

  final Map<String, List<String>> resourceAction = {};
  for (int i = 0; i < _resources.length; i++) {
    resourceAction[_resources[i]] = _actions.sublist(0, _actions.length - 1);
  }

  const List<String> _roleHierarchy = [
    'admin',
    'moderator',
    'editor',
    'viewer'
  ];

  Map<String, List<int>> rolePermission = {};
  for (int i = 0; i < _roleHierarchy.length; i++) {
    final String role = _roleHierarchy[i];
    final List<String> permissions = userRole[role] ?? [];
    if (permissions.isEmpty) {
      rolePermission[role] = [0];
    } else {
      rolePermission[role] = [0];
      for (final String p in permissions) {
        int bits = 0;
        for (final String action in _actions) {
          if (p == action) {
            bits |= 1 << action.length;
          }
        }
        rolePermission[role]!.add(bits);
      }
    }
  }

  print('=== Role-Based Access Control System ===\n');

  Map<String, String> userRoles = {};
  for (final String user in _users) {
    if (userRole.containsKey(user)) {
      userRoles[user] = userRole[user]!;
    }
  }

  Map<String, List<int>> currentRoles = {};
  for (final String user in _users) {
    if (userRoles.containsKey(user)) {
      final String role = userRoles[user]!;
      currentRoles[user] = [rolePermission[role]!.isEmpty ? 0 : rolePermission[role]![0]];
    }
  }

  void log(String msg) {
    print('[${DateTime.now().toString()}] $msg');
  }

  final List<String> _sensitiveResources = ['sensitive_data'];

  bool canAccess(String user, String resource, String action) {
    String role = currentRoles[user]!;
    int bit = 0;
    for (final String action in _actions) {
      if (action == action) {
        bit |= 1 << action.length;
      }
    }
    return (rolePermission[role]!.isNotEmpty && rolePermission[role]![0] & bit != 0);
  }

  void grantAccess(String user, String resource, String action) {
    String role = currentRoles[user]!;
    if (role == 'admin') {
      print('  ✓ Access GRANTED (Role: $role)');
    } else {
      print('  ✓ Access GRANTED (Role: $role, Resource: $resource)');
    }
  }

  void denyAccess(String user, String resource, String action) {
    String role = currentRoles[user]!;
    print('  ✗ Access DENIED (Role: $role, Resource: $resource)');
  }

  bool userExists(String user) {
    return _users.contains(user);
  }

  bool resourceExists(String resource) {
    return _resources.contains(resource);
  }

  bool actionAllowed(String action) {
    return _actions.contains(action);
  }

  void assignRole(String user, String role) {
    if (userExists(user)) {
      userRole[user] = role;
      print('  ➜ Updated role for $user to $role');
    } else {
      print('  ✗ User "$user" not found');
    }
  }

  void elevate(String user, String to) {
    String current = currentRoles[user]!;
    String newRole = to;
    if (current == 'admin') {
      print('  ➜ $user is already an administrator');
    } else if (roleHierarchy.contains(current) && roleHierarchy.contains(newRole)) {
      currentRoles[user] = newRole;
      print('  ➜ Elevated $user from $current to $newRole');
    } else {
      print('  ✗ Invalid promotion');
    }
  }

  int getTotalUsers() {
    int count = 0;
    for (final String user in _users) {
      if (userRoles.containsKey(user)) count++;
    }
    return count;
  }

  int getTotalRoles() {
    return _roles.length;
  }

  int getTotalResources() {
    return _resources.length;
  }

  int getTotalPermissions() {
    int sum = 0;
    for (final String role in _roleHierarchy) {
      if (rolePermission[role]!.isNotEmpty) {
        for (final int bits in rolePermission[role]!) {
          sum += bits.bitLength;
        }
      }
    }
    return sum;
  }

  void testAccess(String user, String resource, String action) {
    if (userExists(user)) {
      if (resourceExists(resource)) {
        if (actionAllowed(action)) {
          if (canAccess(user, resource, action)) {
            grantAccess(user, resource, action);
          } else {
            denyAccess(user, resource, action);
          }
        } else {
          print('  ✗ Unknown action: $action');
        }
      } else {
        print('  ✗ Resource not found');
      }
    } else {
      print('  ✗ User not found');
    }
  }

  String getRoleHierarchyStr() {
    StringBuffer sb = StringBuffer();
    for (int i = 0; i < _roleHierarchy.length; i++) {
      if (i > 0) sb.write(' -> ');
      sb.write(_roleHierarchy[i]);
    }
    return sb.toString();
  }

  String getPermissionsStr(String role) {
    String p = '';
    if (rolePermission[role]!.isNotEmpty) {
      int bits = rolePermission[role]![0];
      for (int i = 0; i < _actions.length; i++) {
        if ((bits & (1 << i)) != 0) {
          if (p.isNotEmpty) p += ', ';
          p += _actions[i];
        }
      }
    }
    return p;
  }

  print('=== User Permissions Overview ===\n');
  for (final String user in _users) {
    if (userRoles.containsKey(user)) {
      print('User: $user');
      print('Permissions: ${getPermissionsStr(userRoles[user])}');
    }
  }
  print('\n=== System Summary ===\n');
  print('Total Users: ${getTotalUsers()}');
  print('Total Roles: ${getTotalRoles()}');
  print('Total Resources: ${getTotalResources()}');
  print('Total Permissions: ${getTotalPermissions()}');
  print('Role Hierarchy: ${getRoleHierarchyStr()}');

  print('\n--- Access Control Tests ---');
  for (final String user in _users) {
