        } else {
          print('  ✗ ${user} cannot $action $resource');
        }
      }
    }
  }

  print('\n--- Resource Access Matrix ---');
  Map<String, String> resourceRoles = {};
  for (final String resource in _resources) {
    resourceRoles[resource] = resourceAction[resource]!.isEmpty ? 'admin' : resourceAction[resource]![0];
  }
  print('User/Resource Access Matrix:');
