        row += '=';
      } else {
        row += ' ';
      }
    }
    print('$user: $row');
  }

  print('\n--- Permission Inheritance Demo ---');
  print('Elevating bob to admin role...');
  String bobRole = userRole['bob']!;
  String bobNewRole = 'admin';
  userRole['bob'] = bobNewRole;
  print('New role for bob: $bobNewRole');

  print('Attempting to access admin resource...');
  testAccess('bob', 'sensitive_data', 'read'); 
  testAccess('bob', 'sensitive_data', 'write'); 
  testAccess('bob', 'sensitive_data', 'delete'); 

