          break;
        }
      }
    }

    Map<int, Set<int>> candidates = {};
    for (Set<int> itemset in frequentItemsets) {
      for (int i = 1; i <= itemset.length; i++) {
        Set<int> candidate = itemset.toList()..addAll(itemset);
        candidates[i] = candidate;
      }
    }

    List<Set<int>> frequentCandidates = [];
    for (int i = 1; i <= candidates.length; i++) {
      int minSupportCount = minSupport * totalTransactions / 2;
      if (candidates[i]?.length == minSupport && supportCount[candidates[i]]! >= minSupportCount) {
        frequentCandidates.add(candidates[i]!);
      }
    }

    frequentItemsets.addAll(frequentCandidates);
  }

