          sub.sort();
          final String key = sub.join(' ');
          if (!crossAssociation.containsKey(key)) {
            crossAssociation[key] = <String>{};
          }
          crossAssociation[key]!.add(subTrans.join(' '));
        }
      }
      final Set<String> candidates = crossAssociation.entries.where((e) => e.value.length == itemset.length).map((e) => e.key).toList();
      for (final candidate in candidates) {
        if (candidate.isEmpty) {
          continue;
        }
        final Map<String, int> freq = <String, int>{};
        for (final transaction in transactions) {
          if (transaction.contains(candidate)) {
