          }
        }
      }
    }

    final Set<String> frequent = <String>[];
    for (final entry in freqOfFreq.entries) {
      final int count = entry.value;
      if (count * transactions.length >= minSupport) {
        frequent.add(entry.key);
      }
    }

    if (frequent.isEmpty) {
      break;
    }

    currentItemset = frequent.join(' ');
    final int prevFrequent = maxFrequent[currentItemset] ?? 0;
    if (prevFrequent == 0 || freqOfFreq[currentItemset]! > prevFrequent) {
      maxFrequent[currentItemset] = freqOfFreq[currentItemset]!;
      if (maxFrequent[currentItemset]! > maxFrequentCount) {
        maxFrequentCount = maxFrequent[currentItemset]!;
      }
    }
