  int cols = grid[0].length;

  List<int> result = <int>[];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] == 0) {
        continue;
      }

      List<List<int>> sub = <List<int>>[];
      List<int> dir = <int>[];

      if (r > 0) {
        sub.add(<int>[grid[r-1][c]]);
        dir.add(<int>[1, 0]);
      }
      if (c > 0) {
        sub.add(<int>[grid[r][c-1]]);
