        sub.add(<int>[grid[r+1][c]]);
        dir.add(<int>[1, 0]);
      }
      if (c < cols - 1) {
        sub.add(<int>[grid[r][c+1]]);
        dir.add(<int>[0, -1]);
      }

      int v = grid[r][c];
      List<int> weights = <int>[];
      for (List<int> s in sub) {
        weights.add(s[0] == v ? 3 : s[0] == v - 1 ? 2 : s[0] == v + 1 ? 1 : 0);
      }

      if (weights.isEmpty) {
        continue;
      }

      int sum = 0;
      for (int i = 0; i < weights.length; i++) {
        sum += weights[i];
