    [1.5, 2.5],
    [4.0, 2.0],
    [1.0, 1.5],
  ];

  const int k = 3; 
  const double eps = 1e-4; 
  const int maxIterations = 100;

  List<List<double>> points = List.from(data);
  List<int> clusters = List.filled(points.length, 0);

  Set<int> visited = {};

  int find(int i) {
    if (clusters[i] == 0) {
      clusters[i] = i;
      visited.add(i);
      return i;
    }
    return clusters[i] = find(clusters[i]);
  }

  void union(int a, int b) {
    a = find(a);
    b = find(b);
    if (a != b) {
      if (a.isEven) clusters[a] = b;
      else clusters[b] = a;
    }
  }

  for (int i = 0; i < points.length; i++) {
    if (visited.contains(i)) continue;
    visited.add(i);
    clusters[i] = i;
  }

  for (int iter = 0; iter < maxIterations; iter++) {
    int change = 0;

    for (int i = 0; i < points.length; i++) {
      if (visited.contains(i)) continue;
      visited.add(i);
      clusters[i] = i;
    }

    for (int i = 0; i < points.length; i++) {
      if (visited.contains(i)) continue;
      visited.add(i);

      int c = clusters[i];
      double d = double.infinity;
      int best = c;

      for (int j = 0; j < points.length; j++) {
        if (visited.contains(j)) continue;
        visited.add(j);
        double dist = (points[i][0] - points[j][0]).abs() +
            (points[i][1] - points[j][1]).abs();
        if (dist < d) {
          d = dist;
          best = j;
        }
      }

      if (d <= eps) {
        change++;
        union(c, best);
      }
    }

    if (change == 0) break;

    print('Converged in $iter iteration(s).');
  }

  for (int c = 0; c < k; c++) {
    List<int> indices = [];
    for (int i = 0; i < points.length; i++) {
      if (clusters[i] == c) indices.add(i);
    }
    print('Cluster $c: ${indices.join(', ')}');
  }
}

