    final newClusterLabels = List<int>.filled(data.length, -1);

    for (int i = 0; i < data.length; i++) {
      double minDist = double.infinity;
      int bestCluster = -1;

      for (int c = 0; c < k; c++) {
        double dist = euclideanDistance(data[i], centroids[c]);
        if (dist < minDist) {
          minDist = dist;
          bestCluster = c;
        }
      }

      if (clusterLabels[i] == -1) {
        newClusterLabels[i] = bestCluster;
      } else if (minDist > eps) {
        newClusterLabels[i] = clusterLabels[i];
      }
