      if (pointsInClusters[c].isEmpty) {
        centroidsNew[c] = List<double>.from(data[c]);
      } else {
        double meanX = 0, meanY = 0;
        for (final point in pointsInClusters[c]) {
          meanX += point[0];
          meanY += point[1];
