Future<void> fn0() async {

  Stream<int> getOddNumbers(int n) async* {
    int start = 1;
    while (start <= n) {
      yield start;
      start += 2;
    }
  }

  Stream<int> combineOddNumbers(Stream<int> source) async* {
    yield 0;
    yield* source;
    yield* getOddNumbers(5);
    yield* getOddNumbers(3);
    yield* getOddNumbers(7);
    yield* getOddNumbers(1);
  }

  print('Starting combined odd number stream...');
  var combined = combineOddNumbers(getOddNumbers(10));

  for (var num in combined) {
    print('Odd number: $num');
  }

  print('Stream processing complete.');
}

