  int total = n * n;
  for (int idx = 0; idx < total; idx++) {
    int row = idx ~/ n;
    int col = idx % n;
    if (row == 0 || row == n - 1 || col == 0 || col == n - 1) {
      bool hasEdge = false;
      for (int i = 0; i < n; i++) {
        if (grid[row][i] != grid[row - 1][i]) {
          hasEdge = true;
