bool fn0(List<int> samples) {
  if (samples.length < 2) return false;
  for (int i = 0; i + 1 < samples.length; i += 2) {
    int a = samples[i], b = samples[i + 1];
    if (a.abs() + b.abs() != samples[0].abs()) return false;
    if (a == b) return false;
    bool coprime = true;
    for (int d = 2; d * d <= a && d * d <= b; d++) {
      if (a % d == 0 || b % d == 0) {
        coprime = false;
        break;
      }
    }
    if (!coprime) return false;
  }
  return true;
}

