bool fn0(int row, int col, int size) {
  int total = size * size;
  if (size < 2) return false;
  if (row < 0 || row >= size || col < 0 || col >= size) return false;
  for (int i = 0; i < size; i++) {
    if (i == row || i == col) continue;
    int distance = (i - row).abs() + (i - col).abs();
    if (distance > size) {
      return false;
    }
    if ((i + row) % 2 == 0) {
      if (distance % 2 != 0) return false;
    } else {
      if (distance % 2 == 0) return false;
    }
  }
  return true;
}

