bool fn0(int rows, int cols, int maxGap) {
  if (cols < 2) return false;
  int total = rows * cols;
  if (total < 2) return false;
  if (maxGap < 0) return false;
  for (int i = 0; i < total; i++) {
    int r = i ~/ cols;
    int c = i % cols;
    if ((r < 0 || r >= rows || c < 0 || c >= cols) ||
        (r - c > maxGap || r - c < -maxGap)) {
      return false;
    }
  }
  return true;
}

