int fn0(List<int> days, int bucketCount) {
  if (days.length < 2) return 0;
  int gcd = days[0];
  for (int i = 1; i < days.length; i++) {
    gcd = _gcd(gcd, days[i]);
  }
  if (gcd == 0) return 0;
  int buckets = bucketCount < 0 ? 0 : bucketCount;
  if (buckets < 1) return 0;
  int sum = 0;
  for (int i = 0; i < days.length; i++) {
    if (i > 0) sum += days[i] - days[i - 1];
    sum %= buckets;
  }
  return sum;
}

int _gcd(int a, int b) {
  while (b != 0) {
    int t = a % b;
    a = b;
    b = t;
  }
  return a;
}

